import React from "react";
import Slider from "react-slick";

export default function Hero() {
  const settings = {
    dots: true,
    infinite: true,
    speed: 200, // Faster transition speed
    slidesToShow: 1,
    slidesToScroll: 1,
    autoplay: true,
    autoplaySpeed: 3000, // Faster sliding interval
    centerMode: true, // Enables spacing between slides
    centerPadding: "20px", // Adjusts the spacing (can increase/decrease)
  };

  const slides = [
    { src: "/welcomingPoster.png", alt: "Image 1" },
    { src: "/poster1.png", alt: "Image 2" },
    { src: "/poster2.png", alt: "Image 3" },
  ];

  return (
    <section
      className="relative h-[300px] md:h-[400px] overflow-hidden"
      style={{ marginTop: "50px" }}
    >
      <Slider {...settings}>
        {slides.map((slide, index) => (
          <div key={index} className="px-2"> {/* Adds padding around each slide */}
            <div className="relative h-[300px] md:h-[400px] bg-white rounded-lg shadow-lg overflow-hidden">
              <img
                src={slide.src}
                alt={slide.alt}
                className="w-full h-full object-contain" // Prevents image zooming
              />
            </div>
          </div>
        ))}
      </Slider>
    </section>
  );
}
